  const IC_BLOCK = pxImg('ic_guard', 12);

  /* --- 피격 반응 표식 --- */
  const IC_DODGE   = pxImg('ic_dodge', 12);    /* 회피 */
  const IC_GUARDED = pxImg('ic_guard', 12);    /* 흘려막기 */
  const IC_RIPOSTE = pxImg('ic_riposte', 12);  /* 반격 */

  /* 나중에 합류하는 셋 — assets/클래스1.png · 클래스2.png 에서 흉상만 오려 왔다.
     작살과 밧줄을 든 쪽이 작살광전사 브란, 등잔과 갈고리를 든 쪽이 난파도굴꾼 카쿠스,
     해골 지팡이에 보라 불을 얹은 쪽이 진혼악사 다윗이다 — 보라는 이미 이 병과의 색이다. */
  const ICON_HELLION = '<img src="data:image/jpeg;base64," alt="" draggable="false" style="width:100%;height:100%;object-fit:cover;display:block;">';
  const ICON_ROBBER = '<img src="data:image/jpeg;base64," alt="" draggable="false" style="width:100%;height:100%;object-fit:cover;display:block;">';
  const ICON_JESTER = '<img src="data:image/jpeg;base64," alt="" draggable="false" style="width:100%;height:100%;object-fit:cover;display:block;">';

  const CLASS_ICON = {
    vanguard: ICON_VANGUARD, chemist: ICON_CHEMIST, priest: ICON_PRIEST, oracle: ICON_ORACLE,
    hellion: ICON_HELLION, robber: ICON_ROBBER, jester: ICON_JESTER,
  };

  /* ============ 사거리 ============
     다키스트던전식 — 서 있는 열이 곧 화력이다.
       from : 이 병과가 공격을 시작할 수 있는 "자기 열"
       hits : 그때 닿을 수 있는 "상대 열"
     근접이 후열로 밀려나면 from 을 벗어나 전열을 때릴 수 없고,
     원거리가 전열로 끌려나오면 조준할 자리가 없어 무력해진다. */
  const REACH = {
    melee:  {id:'melee',  label:'근접',   from:[0,1],   hits:[0,1],
             note:'전열·중열에서만 휘두를 수 있다'},
    mid:    {id:'mid',    label:'중거리', from:[0,1,2], hits:[0,1,2,3],
             note:'후미(심부)에서는 손이 닿지 않는다'},
    ranged: {id:'ranged', label:'원거리', from:[1,2,3,4], hits:[0,1,2,3,4],
             note:'전열에 서면 조준할 자리가 없다'},
  };
  function reachOf(unit){ return REACH[unit && unit.reach] || REACH.mid; }
  /* '유연한 몸놀림' 각인을 지닌 대원은 사거리 표를 무시하고 어느 자리에서든
     행동할 수 있다 — 공격 판정(canHitRank)까지는 안 풀어 준다, 자리 제약만 푼다. */
  function canActFrom(unit, rank){ if(unit && unit.reachFlexible) return true; return reachOf(unit).from.indexOf(rank) >= 0; }
  function canHitRank(unit, rank){ return reachOf(unit).hits.indexOf(rank) >= 0; }

  /* 피격 반응 성향 — 앞에 설수록 받아치고, 뒤에 설수록 비껴난다 */
  const REACT = {
    melee:  {dodge:0.08, guard:0.24, riposte:0.30, rip:5},
    mid:    {dodge:0.15, guard:0.15, riposte:0.14, rip:3},
    ranged: {dodge:0.24, guard:0.07, riposte:0.05, rip:2},
  };
  /* 개체별 reactMod 가 있으면 그것이 사거리 기본값을 덮어쓴다 (갑각은 잘 흘리고, 해파리는 잘 피한다) */
  function reactOf(unit){
    const base = (unit && unit.reactMod) || REACT[unit && unit.reach] || REACT.mid;
    if(!unit || !unit.isHero) return base;
    /* 유물은 아군에게만 붙는다 — 적은 언제나 맨몸의 기본값으로 판정한다 */
    const veteranReact = unit.descentReact || 0;
    /* 난파도굴꾼 — 은신에 익어 몸을 비트는 데 남들보다 빠르다 */
    const classDodgeBonus = unit.cls==='robber' ? ROBBER_DODGE_BONUS : 0;
    return {
      dodge:   Math.min(0.50, base.dodge   + classDodgeBonus + relicSum('dodge', unit) + veteranReact),
      guard:   Math.min(0.55, base.guard   + relicSum('guard', unit) + veteranReact),
      riposte: Math.min(0.55, base.riposte + relicSum('riposte', unit)),
      rip:     base.rip + relicSum('rip', unit),
    };
  }
